-- Isolated contract-coherence fixture; no application/schema weakening.
-- Existing fixture bypasses, if any, are preserved historical test seams; no new
-- trigger bypass, permission grant, production defaults or business records added.
begin;
-- Isolated local data; never applied to a hosted company. Runner rolls back.
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
alter table auth.users disable trigger on_auth_user_created;
insert into auth.users(id,email) values('e1100000-0000-4000-8000-000000000001','readiness-owner@local.invalid');
alter table auth.users enable trigger on_auth_user_created;
insert into public.companies(id,name,operating_timezone) values('e1200000-0000-4000-8000-000000000001','Synthetic readiness contractor','Pacific/Auckland'),('e1200000-0000-4000-8000-000000000002','Other synthetic contractor','UTC');
insert into public.profiles(id,company_id,role,full_name) values('e1100000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','owner','Synthetic owner');
insert into public.projects(id,company_id,job_number,name,status,sales_tax_exempt) values('e1300000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','SYN-READY','Synthetic readiness job','active',true),('e1300000-0000-4000-8000-000000000002','e1200000-0000-4000-8000-000000000002','SYN-FOREIGN','Foreign job','active',true);
-- Explicit synthetic historical agreement input; not hosted acceptance proof.
insert into public.project_award_records(company_id,project_id,agreement_number,original_contract_value,status,authorization_text) values('e1200000-0000-4000-8000-000000000001','e1300000-0000-4000-8000-000000000001','SYN-AG',0,'accepted','Synthetic historical fixture agreement evidence; no real customer authorization');
insert into public.production_tasks(id,company_id,name,production_unit,active) values('e1500000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','Synthetic finish','SF',true);
insert into public.work_packages(id,company_id,project_id,name,planned_start_date) values('e1600000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','e1300000-0000-4000-8000-000000000001','Synthetic package','2026-10-20');
insert into public.work_package_operations(id,company_id,work_package_id,production_task_id,field_label,planned_quantity,unit,requires_prior_operations,sequence) values('e1700000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','e1600000-0000-4000-8000-000000000001','e1500000-0000-4000-8000-000000000001','Synthetic finish',100,'SF',false,10),('e1700000-0000-4000-8000-000000000002','e1200000-0000-4000-8000-000000000001','e1600000-0000-4000-8000-000000000001','e1500000-0000-4000-8000-000000000001','Second ready work',100,'SF',false,20);
select set_config('request.jwt.claim.sub','e1100000-0000-4000-8000-000000000001',true);
set local role authenticated;
select extensions.ok((select ready_to_start_all from public.work_package_start_readiness where operation_id='e1700000-0000-4000-8000-000000000001'),'fully clear persisted facts produce ready work');
reset role;
insert into public.project_inspections(id,company_id,project_id,required_for_operation_id,title,status) values('e1800000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','e1300000-0000-4000-8000-000000000001','e1700000-0000-4000-8000-000000000001','Synthetic required inspection','required');
set local role authenticated;
select extensions.ok((select not ready_to_start_all and inspection_blocking_count=1 from public.work_package_start_readiness where operation_id='e1700000-0000-4000-8000-000000000001'),'required inspection blocks start');
update public.project_inspections set status='cancelled' where id='e1800000-0000-4000-8000-000000000001';
select extensions.ok((select not ready_to_start_all and inspection_blocking_count=1 and inspection_clear_count=0 from public.work_package_start_readiness where operation_id='e1700000-0000-4000-8000-000000000001'),'canceled required inspection remains a hold until passed or waived');
select extensions.ok((select start_next_action like '%Synthetic required inspection%' from public.work_package_start_readiness where operation_id='e1700000-0000-4000-8000-000000000001'),'canceled inspection retains its exact governing context');
select extensions.is((select ready_operation_count from public.project_work_readiness_summary),1,'ready work remains counted beside blocked work');
select extensions.is((select blocked_operation_count from public.project_work_readiness_summary),1,'blocked work remains visible beside ready work');
update public.project_inspections set status='passed' where id='e1800000-0000-4000-8000-000000000001';
select extensions.ok((select ready_to_start_all and inspection_clear_count=1 from public.work_package_start_readiness where operation_id='e1700000-0000-4000-8000-000000000001'),'passing result clears required inspection');
update public.project_inspections set status='waived',waived_reason='Explicit synthetic owner waiver with retained evidence',updated_by=auth.uid(),completed_at=clock_timestamp() where id='e1800000-0000-4000-8000-000000000001';
select extensions.ok((select ready_to_start_all from public.work_package_start_readiness where operation_id='e1700000-0000-4000-8000-000000000001'),'explicit waiver clears inspection');
update public.work_package_operations set status='on_hold',readiness_hold_reason=null where id='e1700000-0000-4000-8000-000000000001';
select extensions.ok((select not ready_to_start_all and readiness_status='management_hold' from public.work_package_start_readiness where operation_id='e1700000-0000-4000-8000-000000000001'),'explicit operation hold cannot disappear when its explanation is absent');
update public.work_package_operations set status='planned' where id='e1700000-0000-4000-8000-000000000001';
reset role;
insert into public.inventory_items(id,company_id,name,unit,quantity_on_hand,reorder_point) values('e1810000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','Synthetic materials','EA',10,0),('e1810000-0000-4000-8000-000000000002','e1200000-0000-4000-8000-000000000001','Different materials','EA',100,0);
insert into public.work_package_resource_requirements(id,company_id,work_package_operation_id,resource_type,label,required_quantity,unit,inventory_item_id,required_before_start,need_offset_days) values('e1820000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','e1700000-0000-4000-8000-000000000001','material','Synthetic start materials',4,'EA','e1810000-0000-4000-8000-000000000001',true,-2);
set local role authenticated;
select extensions.ok((select ready_to_start and not ready_to_start_all and blocking_resource_count=1 from public.work_package_start_readiness where operation_id='e1700000-0000-4000-8000-000000000001'),'base readiness does not erase a connected required-resource hold');
select extensions.is((select need_by_date from public.work_package_resource_requirement_status),'2026-10-18'::date,'signed schedule offset follows captured deployed contract');
reset role;
insert into public.inventory_reservations(company_id,resource_requirement_id,inventory_item_id,quantity,status) values('e1200000-0000-4000-8000-000000000001','e1820000-0000-4000-8000-000000000001','e1810000-0000-4000-8000-000000000001',4,'reserved');
set local role authenticated;
select extensions.ok((select ready_to_start_all from public.work_package_start_readiness where operation_id='e1700000-0000-4000-8000-000000000001'),'reserved known stock clears required material');
reset role;
update public.inventory_reservations set inventory_item_id='e1810000-0000-4000-8000-000000000002';
set local role authenticated;
select extensions.ok((select not ready_to_start_all from public.work_package_start_readiness where operation_id='e1700000-0000-4000-8000-000000000001'),'reservation for another inventory item cannot clear this requirement');
reset role;
update public.inventory_reservations set inventory_item_id='e1810000-0000-4000-8000-000000000001';
update public.inventory_items set quantity_on_hand=2 where id='e1810000-0000-4000-8000-000000000001';
set local role authenticated;
select extensions.is((select shortage_quantity from public.work_package_resource_requirement_status),2::numeric,'stock shortage uses actual available reserved quantity');
select extensions.ok((select not ready_to_start_all from public.work_package_start_readiness where operation_id='e1700000-0000-4000-8000-000000000001'),'insufficient on-hand stock blocks physical start');
reset role;
update public.inventory_items set quantity_on_hand=10 where id='e1810000-0000-4000-8000-000000000001';
insert into public.work_package_resource_requirements(id,company_id,work_package_operation_id,resource_type,label,required_quantity,unit,vendor_status,required_before_start) values('e1820000-0000-4000-8000-000000000002','e1200000-0000-4000-8000-000000000001','e1700000-0000-4000-8000-000000000001','vendor','Synthetic testing agency',1,'EA','confirmed',true);
set local role authenticated;
select extensions.ok((select resource_status<>'ready' and blocking_reason like '%no vendor selected%' from public.work_package_resource_requirement_status where id='e1820000-0000-4000-8000-000000000002'),'confirmation without an identified vendor does not imply clearance');
select extensions.is((select blocking_resource_count from public.work_package_start_readiness where operation_id='e1700000-0000-4000-8000-000000000001'),1,'missing vendor contributes to authoritative resource count');
select extensions.lives_ok($$select public.carez_schedule_command_v1('e1900000-0000-4000-8000-000000000001','create','{"project_id":"e1300000-0000-4000-8000-000000000001","schedule_date":"2026-10-20","item_type":"work","work_package_operation_id":"e1700000-0000-4000-8000-000000000001","crew_needed":0,"crew_member_ids":[]}')$$,'held work remains plannable');
select extensions.ok((select not ready_to_start and blocking_resource_count=1 from public.work_package_lookahead),'lookahead uses full connected start gate');
select extensions.throws_like($$select public.carez_schedule_command_v1('e1900000-0000-4000-8000-000000000002','status',(select jsonb_build_object('id',id,'expected_revision',command_revision,'status','confirmed') from public.work_schedule_items where item_type='work'))$$,'%Work is on hold:%','schedule confirmation reuses connected resource authority');
select extensions.is((select count(*)::int from public.work_package_start_readiness where company_id='e1200000-0000-4000-8000-000000000002'),0,'invoker views do not expose another tenant');
reset role;
-- Populated local supply cases: consumed stock, received PO material and dated equipment.
set local role postgres;
insert into public.vendors(id,company_id,name) values('e1830000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','Synthetic supplier');
insert into public.cost_codes(id,company_id,code,name,cost_type) values('e1840000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','SYN-MAT','Synthetic materials','material');
insert into public.inventory_items(id,company_id,name,unit,quantity_on_hand,reorder_point) values('e1810000-0000-4000-8000-000000000003','e1200000-0000-4000-8000-000000000001','Previously supplied stock','EA',0,0);
insert into public.work_package_resource_requirements(id,company_id,work_package_operation_id,resource_type,label,required_quantity,unit,inventory_item_id,required_before_start) values('e1820000-0000-4000-8000-000000000003','e1200000-0000-4000-8000-000000000001','e1700000-0000-4000-8000-000000000002','material','Combined consumed and delivered supply',10,'EA','e1810000-0000-4000-8000-000000000003',true);
insert into public.inventory_reservations(company_id,resource_requirement_id,inventory_item_id,quantity,status) values('e1200000-0000-4000-8000-000000000001','e1820000-0000-4000-8000-000000000003','e1810000-0000-4000-8000-000000000003',4,'consumed');
create temp table supply_results(key text primary key,value jsonb);grant all on supply_results to authenticated;
create function pg_temp.supply(n integer,c text,p jsonb) returns jsonb language sql as $$select public.carez_procurement_command_v1(('e1910000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,c,p)$$;
create function pg_temp.resource(n integer,c text,p jsonb) returns jsonb language sql as $$select public.carez_resource_command_v1(('e1920000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,c,p)$$;
reset role;set local role authenticated;
insert into supply_results values('po',pg_temp.supply(1,'create_po','{"project_id":"e1300000-0000-4000-8000-000000000001","vendor_id":"e1830000-0000-4000-8000-000000000001","expected_delivery_date":"2026-10-20"}'));
insert into supply_results values('line',pg_temp.supply(2,'add_po_line',(select jsonb_build_object('purchase_order_id',value->>'id','cost_code_id','e1840000-0000-4000-8000-000000000001','description','Delivered material','quantity',6,'unit','EA','unit_cost',1,'sales_tax',0) from supply_results where key='po')));
select pg_temp.supply(3,'issue_po',(select jsonb_build_object('purchase_order_id',value->>'id','issue_date','2026-10-16') from supply_results where key='po'));
select pg_temp.resource(1,'link_po',(select jsonb_build_object('requirement_id','e1820000-0000-4000-8000-000000000003','purchase_order_line_id',value->>'id') from supply_results where key='line'));
select pg_temp.supply(4,'receipt',jsonb_build_object('purchase_order_id',(select value->>'id' from supply_results where key='po'),'purchase_order_line_id',(select value->>'id' from supply_results where key='line'),'quantity_received',6,'received_date','2026-10-20'));
select extensions.ok((select safe_inventory_qty=4 and received_qty=6 and shortage_quantity=0 and resource_status='ready' from public.work_package_resource_requirement_status where id='e1820000-0000-4000-8000-000000000003'),'consumed four plus received six clear ten even when warehouse stock is zero');
reset role;set local role postgres;
-- Model a pre-existing ambiguous linkage without invoking an application mutation.
insert into public.work_package_resource_requirements(id,company_id,work_package_operation_id,resource_type,label,required_quantity,unit,purchase_order_line_id,required_before_start) select 'e1820000-0000-4000-8000-000000000004','e1200000-0000-4000-8000-000000000001','e1700000-0000-4000-8000-000000000002','material','Ambiguous legacy demand',6,'EA',(value->>'id')::uuid,true from supply_results where key='line';
reset role;set local role authenticated;
select extensions.is((select count(*)::int from public.work_package_resource_requirement_status where id in ('e1820000-0000-4000-8000-000000000003','e1820000-0000-4000-8000-000000000004') and received_qty=0 and resource_status<>'ready' and blocking_reason like '%distinct source lines%'),2,'ambiguous legacy PO linkage never credits its full receipt twice');
reset role;set local role postgres;
insert into public.equipment_assets(id,company_id,name,status,active) values('e1850000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','Synthetic dated equipment','available',true);
reset role;set local role authenticated;
insert into supply_results values('equipment',pg_temp.resource(2,'create','{"work_package_operation_id":"e1700000-0000-4000-8000-000000000002","resource_type":"equipment","label":"Dated equipment","required_quantity":1,"unit":"EA","equipment_asset_id":"e1850000-0000-4000-8000-000000000001","reservation_start":"2026-10-18","reservation_end":"2026-10-19","need_by_override":"2026-10-20","equipment_confirmed":true,"required_before_start":true}'));
select extensions.ok((select resource_status='blocked' and blocking_reason like '%does not cover the work date%' from public.work_package_resource_requirement_status where id=(select (value->>'id')::uuid from supply_results where key='equipment')),'confirmed booking outside the governing date remains held');
select pg_temp.resource(3,'reserve_equipment',(select jsonb_build_object('requirement_id',value->>'id','equipment_asset_id','e1850000-0000-4000-8000-000000000001','start_date','2026-10-20','end_date','2026-10-21','confirmed',true) from supply_results where key='equipment'));
select extensions.ok((select resource_status='ready' and blocking_reason is null from public.work_package_resource_requirement_status where id=(select (value->>'id')::uuid from supply_results where key='equipment')),'confirmed booking covering the governing date clears that requirement');
insert into supply_results values('conflict',pg_temp.resource(4,'create','{"work_package_operation_id":"e1700000-0000-4000-8000-000000000002","resource_type":"equipment","label":"Overlapping equipment","required_quantity":1,"unit":"EA","equipment_asset_id":"e1850000-0000-4000-8000-000000000001","reservation_start":"2026-10-20","reservation_end":"2026-10-20","need_by_override":"2026-10-20","equipment_confirmed":true,"required_before_start":true}'));
select extensions.ok((select resource_status='blocked' and blocking_reason like '%conflicting work%' from public.work_package_resource_requirement_status where id=(select (value->>'id')::uuid from supply_results where key='equipment')),'overlapping booking remains a distinct blocking reason');
reset role;
create temp table original_job_readiness as select pg_get_viewdef('public.project_job_readiness_summary'::regclass,true) definition;
do $$declare d text;begin select rtrim(btrim(definition),';') into d from original_job_readiness;execute 'create or replace view public.project_job_readiness_summary with(security_invoker=true) as select * from ('||d||')j where false';end $$;
set local role authenticated;
select extensions.ok((select not job_setup_ready and not ready_to_start_all and start_next_action='Job setup readiness unavailable' from public.work_package_start_readiness where operation_id='e1700000-0000-4000-8000-000000000002'),'successfully missing job readiness remains unavailable and fails closed');
reset role;
do $$declare d text;begin select definition into d from original_job_readiness;execute 'create or replace view public.project_job_readiness_summary with(security_invoker=true) as '||d;end $$;
select extensions.ok((select format_type(atttypid,atttypmod) in ('numeric(14,4)','numeric') from pg_attribute where attrelid='public.work_package_operation_readiness'::regclass and attname='planned_quantity'),'readiness exposes a recognized canonical/deployed numeric quantity contract');
select extensions.ok((select format_type(atttypid,atttypmod) in ('text','date') from pg_attribute where attrelid='public.work_package_resource_requirement_status'::regclass and attname='equipment_start_date'),'resource status retains a recognized canonical/deployed equipment date contract');
insert into public.projects(id,company_id,job_number,name,status) values('e1300000-0000-4000-8000-000000000003','e1200000-0000-4000-8000-000000000001','SYN-EMPTY','Synthetic job with no physical work','active');
set local role authenticated;
select extensions.ok((select operation_count=0 and ready_operation_count=0 and blocked_operation_count=0 and readiness_status='no_work' from public.project_work_readiness_summary where project_id='e1300000-0000-4000-8000-000000000003'),'successful absence of physical work remains an explicit zero-count project row');
select * from extensions.finish();rollback;
